function getURLVar(t) {
    var e = []
      , o = String(document.location).split("?");
    if (o[1]) {
        var a = o[1].split("&");
        for (i = 0; i < a.length; i++) {
            var n = a[i].split("=");
            n[0] && n[1] && (e[n[0]] = n[1])
        }
        return e[t] ? e[t] : ""
    }
}

function updateCartState() {
        var $cart = $('#cart');
        var $counter = $('#cart-total');
        var cartText = $counter.text();
        
        // Проверяем, есть ли цифра больше 0 в тексте (например, "2 товара" или "1")
        var matches = cartText.match(/\d+/);
        var count = matches ? parseInt(matches[0]) : 0;

        if (count > 0) {
        $cart.addClass('with_products');
        $counter.show(); // Показываем счетчик
        } else {
        $cart.removeClass('with_products');
        $counter.hide(); // Скрываем счетчик, если 0
        }
}

$(document).ready(function() {
    $(".text-danger").each(function() {
        var t = $(this).parent().parent();
        t.hasClass("form-group") && t.addClass("has-error")
    }),
    $("#form-currency .currency-select").on("click", function(t) {
        t.preventDefault(),
        $("#form-currency input[name='code']").val($(this).attr("name")),
        $("#form-currency").submit()
    }),
    $("#form-language .language-select").on("click", function(t) {
        t.preventDefault(),
        $("#form-language input[name='code']").val($(this).attr("name")),
        $("#form-language").submit()
    }),
    $("#fn_search input[name='search']").parent().find("button").on("click", function() {
        var t = $("base").attr("href") + "index.php?route=product/search"
          , e = $("#fn_search input[name='search']").val();
        e && (t += "&search=" + encodeURIComponent(e)),
        location = t
    }),
    $("#fn_search input[name='search']").on("keydown", function(t) {
        13 == t.keyCode && $("#fn_search input[name='search']").parent().find("button").trigger("click")
    }),
    $("#menu .dropdown-menu").each(function() {
        var t = $("#menu").offset()
          , e = $(this).parent().offset().left + $(this).outerWidth() - (t.left + $("#menu").outerWidth());
        0 < e && $(this).css("margin-left", "-" + (10 + e) + "px")
    }),
    $("#list-view").click(function() {
        $("#content .product-grid > .clearfix").remove(),
        $("#content .row > .product-grid").attr("class", "product-layout product-list col-xs-12"),
        $("#grid-view").removeClass("active"),
        $("#list-view").addClass("active"),
        localStorage.setItem("display", "list")
    }),
    $("#grid-view").click(function() {
        var t = $("#column-right, #column-left").length;
        2 == t ? $("#content .product-list").attr("class", "product-layout product-grid col-lg-6 col-md-6 col-sm-12 col-xs-12") : 1 == t ? $("#content .product-list").attr("class", "product-layout product-grid col-lg-4 col-md-4 col-sm-6 col-xs-12") : $("#content .product-list").attr("class", "product-layout product-grid col-lg-3 col-md-3 col-sm-6 col-xs-12"),
        $("#list-view").removeClass("active"),
        $("#grid-view").addClass("active"),
        localStorage.setItem("display", "grid")
    }),
    "list" == localStorage.getItem("display") ? ($("#list-view").trigger("click"),
    $("#list-view").addClass("active")) : ($("#grid-view").trigger("click"),
    $("#grid-view").addClass("active")),
    $(document).on("keydown", "#collapse-checkout-option input[name='email'], #collapse-checkout-option input[name='password']", function(t) {
        13 == t.keyCode && $("#collapse-checkout-option #button-login").trigger("click")
    }),
    $("[data-toggle='tooltip']").tooltip({
        container: "body"
    }),
    $(document).ajaxStop(function() {
        $("[data-toggle='tooltip']").tooltip({
            container: "body"
        })
    })
    $('.tablet_menu').click(function (){
        $('body').toggleClass('lock');
        $('.mobile-menu').toggleClass('show');
        $('.modal-fon').toggleClass('show');
    });

    function mobileMenuClose(){
         $('.mobile-menu').toggleClass('show');
        $('.modal-fon').removeClass('show');
         $('body').removeClass('lock');
    }

    $('#mobile-menu-close').click(function(e){
        e.preventDefault();
        mobileMenuClose();
    });

    $(document).click(function(event) {
    if ((!$(event.target).closest('.mobile-menu').length)&&($('.mobile-menu').hasClass('show'))&&($('.mobile-menu').css('left') == '0px' ) ) {
        // Клик был вне блока
        mobileMenuClose();
        }
    });

   
    $(window).on("load scroll", function() {
            var e = $(document).scrollTop()
            , t = $(".main").hasClass("product_main");
            $(".main").hasClass("cart_main");
            e < 140 ? ($(".header__bottom, .header__catalog").removeClass("fixed"),
            $('#desktop-menu').removeClass('fixed'),
            $(".main").css("padding-top", "0"),
            t && ($(".tabs_navigation_product").removeClass("fixed"),
            $(".tabs_product_card").removeClass("show"))) : ($(".header__bottom, .header__catalog, #desktop-menu").addClass("fixed"),
            t ? e < 370 ? ($(".tabs_navigation_product").removeClass("fixed"),
            $(".tabs_product_card").removeClass("show"),
            $(".main").css("padding-top", "50px")) : ($(".tabs_navigation_product").addClass("fixed"),
            
            $(".tabs_product_card").addClass("show"),
            $(".main").css("padding-top", "114px")) : $(".main").css("padding-top", "50px"))
    })
    
    updateCartState();

});  // end document ready

$(document).ajaxComplete(function(event, xhr, settings) {
    setTimeout(updateCartState, 200);
});

// Cлайдеры для карточек товаров
    document.addEventListener('DOMContentLoaded', function () {
        
        const productSliders = document.querySelectorAll('.fn_product_images');

        productSliders.forEach(function (sliderEl) {
            // Ищем стрелки именно внутри текущей карточки товара
            const nextBtn = sliderEl.querySelector('.swiper-btn-next_pr');
            const prevBtn = sliderEl.querySelector('.swiper-btn-prev_pr');

            new Swiper(sliderEl, {
                slidesPerView: 1,
                spaceBetween: 10,
                loop: false, // Обычно для мини-слайдеров в сетке loop лучше отключать или настраивать аккуратно
                navigation: {
                    nextEl: nextBtn,
                    prevEl: prevBtn,
                },
            });
        });
    });



var cart = {
    add: function(t, e) {
        $.ajax({
            url: "index.php?route=checkout/cart/add",
            type: "post",
            data: "product_id=" + t + "&quantity=" + (void 0 !== e ? e : 1),
            dataType: "json",
            beforeSend: function() {
                $("#cart > button").button("loading")
            },
            complete: function() {
                $("#cart > button").button("reset")
            },
            success: function(t) {
                $(".alert-dismissible, .text-danger").remove(),
                t.redirect && (location = t.redirect),
                t.success && ($(".nav-menu").after('<div class="event-block"><i class="fa fa-check-circle"></i>' + t.success + "</div>"),
                setTimeout(function() {
                    $("#cart > a").html('<span id="cart-total"><i class="fa fa-shopping-bag" aria-hidden="true"></i> ' + t.total + "</span>")
                }, 100),
                $("#cart ul").load("index.php?route=common/cart/info ul li"))
            },
            error: function(t, e, o) {
                alert(o + "\r\n" + t.statusText + "\r\n" + t.responseText)
            }
        })
    },
    update: function(t, e) {
        $.ajax({
            url: "index.php?route=checkout/cart/edit",
            type: "post",
            data: "key=" + t + "&quantity=" + (void 0 !== e ? e : 1),
            dataType: "json",
            beforeSend: function() {
                $("#cart > button").button("loading")
            },
            complete: function() {
                $("#cart > button").button("reset")
            },
            success: function(t) {
                setTimeout(function() {
                    $("#cart > a").html('<span id="cart-total"><i class="fa fa-shopping-bag" aria-hidden="true"></i> ' + t.total + "</span>")
                }, 100),
                "checkout/cart" == getURLVar("route") || "checkout/checkout" == getURLVar("route") ? location = "index.php?route=checkout/cart" : $("#cart > ul").load("index.php?route=common/cart/info ul li")
            },
            error: function(t, e, o) {
                alert(o + "\r\n" + t.statusText + "\r\n" + t.responseText)
            }
        })
    },
    remove: function(t) {
        $.ajax({
            url: "index.php?route=checkout/cart/remove",
            type: "post",
            data: "key=" + t,
            dataType: "json",
            beforeSend: function() {
                $("#cart > button").button("loading")
            },
            complete: function() {
                $("#cart > button").button("reset")
            },
            success: function(t) {
                setTimeout(function() {
                    $("#cart > a").html('<span id="cart-total"><i class="fa fa-shopping-bag" aria-hidden="true"></i> ' + t.total + "</span>")
                }, 100),
                "checkout/cart" == getURLVar("route") || "checkout/checkout" == getURLVar("route") ? location = "index.php?route=checkout/cart" : $("#cart ul").load("index.php?route=common/cart/info ul li")
            },
            error: function(t, e, o) {
                alert(o + "\r\n" + t.statusText + "\r\n" + t.responseText)
            }
        })
    }
}
